        emit CurveLiquidityGuardUpdated(address(curveLiquidityGuard),guard);
        curveLiquidityGuard=ICurveLiquidityBoundsFXNV49(guard);
    }
    function setConvexCurveLiquidityGuard(address guard) external onlyOwner {_setGuard(guard);}
    function _guard() private view returns(ICurveLiquidityBoundsFXNV49 g) {g=curveLiquidityGuard;if(address(g).code.length==0)revert GuardUnavailable();}
    function allocationTargets() external view returns(uint256,uint256){return(boostCapBps,convexCapBps);}
    function setAllocationTargets(uint16 b,uint16 c) external onlyOwner {if(uint256(b)+c!=MAX_BPS)revert InvalidTargets();boostCapBps=b;convexCapBps=c;emit AllocationCapsUpdated(b,c);}
    function sdFxnToFxnWad() public view returns(uint256) {try IBeefySwapperV2(swapper).getAmountOut(want,fxn,WAD) returns(uint256 a){return a;} catch{return 0;}}
