        if(received==0) revert InvalidExit();convexVault.deposit(received);
    }
    function _invest(uint8 position,uint256 amount) private {if(amount==0)return;if(position==0)staking.deposit(amount,address(this));else {uint256 invested=amount+convexIdle;convexIdle=0;_convexDeposit(invested);}emit Allocation(position,amount);}
    function _allocateAvailable() private {
        uint256 idle=_masterIdle();uint256 locked=lockedProfit();uint256 free=idle>locked?idle-locked:0;if(free==0)return;
        (uint256 b,uint256 c)=_grossPositions();(uint256 bt,uint256 ct)=_targets(idle+IERC20(want).balanceOf(vault)+b+c);
        uint256 bd=bt>b?bt-b:0;uint256 cd=ct>c?ct-c:0;if(cd!=0 && !convexEligible())cd=0;
        if(cd>bd){uint256 x=free<cd?free:cd;_invest(1,x);free-=x;_invest(0,free<bd?free:bd);}
        else{uint256 x=free<bd?free:bd;_invest(0,x);free-=x;_invest(1,free<cd?free:cd);}
    }
    function deposit() external override nonReentrant {_allocateAvailable();}
    function rebalanceAllocations() external nonReentrant {_allocateAvailable();}
    function _redeemLp(uint256 units,bool emergency) private returns(uint256 received){
        uint256 idleLp=IERC20(address(curvePool)).balanceOf(address(this));if(units>idleLp)convexVault.withdraw(units-idleLp);
        uint256 minOut;if(!emergency){(,minOut)=_guard().quoteWithdraw(address(curvePool),1,units,CURVE_LP_SLIPPAGE_BPS);if(minOut==0)revert InvalidExit();}
