        }
        if(convexIdle<amount)revert InvalidExit();convexIdle-=amount;
    }
    function _take(uint8 position,uint256 need,bool emergency,uint256 available) private returns(uint256 requested){
        requested=need<available?need:available;if(requested==0)return 0;uint256 beforeFree=_masterIdle();
        if(position==0)staking.withdraw(requested);else _convexWithdraw(requested,emergency);
        if(_masterIdle()-beforeFree<requested)revert InvalidExit();emit Deallocation(position,requested);
    }
    function withdraw(uint256 amount) external override nonReentrant{_withdrawForVault(amount,false);}
    function emergencyWithdraw(uint256 amount) external nonReentrant{_withdrawForVault(amount,true);}
    function _withdrawForVault(uint256 amount,bool emergency) private {
        if(msg.sender!=vault)revert VaultOnly();(uint256 b,uint256 c)=_netPositions();uint256 idle=_masterIdle();uint256 locked=lockedProfit();
        uint256 sum=idle+b+c;if(amount>(sum>locked?sum-locked:0))revert InvalidExit();if(amount==0)return;
        uint256 free=idle>locked?idle-locked:0;uint256 need=amount>free?amount-free:0;
        if(need!=0){
            uint256 bg=b+positionLockedProfit(0);uint256 cg=c+positionLockedProfit(1);
            uint256 gross=idle+IERC20(want).balanceOf(vault)+bg+cg;(uint256 bt,uint256 ct)=_targets(gross>amount?gross-amount:0);
            uint256 be=bg>bt?bg-bt:0;uint256 ce=cg>ct?cg-ct:0;bool convexFirst=ce>be;
            uint256 got=_take(convexFirst?1:0,need,emergency,convexFirst?c:b);
            if(got<need){(b,c)=_netPositions();_take(convexFirst?0:1,need-got,emergency,convexFirst?b:c);}
        }
        if(_masterIdle()<amount+lockedProfit())revert InvalidExit();IERC20(want).safeTransfer(vault,amount);
    }
    function migrate(uint8 fromStrategyIndex,uint256 sourceUnits) external onlyOwner nonReentrant {
        if(fromStrategyIndex>1 || sourceUnits==0)revert InvalidMigration();uint256 received;(uint256 b,uint256 c)=_netPositions();
        if(fromStrategyIndex==0){if(sdFxnToFxnWad()<=PEG_MIN_WAD || sourceUnits>b)revert InvalidMigration();received=_take(0,sourceUnits,false,b);_invest(1,received);}
        else{if(sourceUnits>gauge.balanceOf(address(convexVault)) || c==0)revert InvalidMigration();(,uint256 minOut)=_guard().quoteWithdraw(address(curvePool),1,sourceUnits,CURVE_LP_SLIPPAGE_BPS);
            if(minOut==0)revert InvalidMigration();uint256 beforeWant=_want();convexVault.withdraw(sourceUnits);
            curvePool.remove_liquidity_one_coin(sourceUnits,1,minOut);received=_want()-beforeWant;if(received==0 || received>c)revert InvalidMigration();_invest(0,received);}
        emit ManualMigration(fromStrategyIndex,sourceUnits,received);
    }
    function lockVaultProfit(uint256 amount) external override {
        if(msg.sender!=vault)revert VaultOnly();if(_masterIdle()<amount+lockedProfit())revert InvalidExit();totalLocked=lockedProfit()+amount;lastHarvest=block.timestamp;
    }
    function _boostRewards() private view returns(address[] memory tokens){
        uint256 n=staking.reward_count();if(n>9)revert InvalidReward();tokens=new address[](n);for(uint256 i;i<n;++i)tokens[i]=staking.reward_tokens(i);
    }
    function _convexRewards() private view returns(address[] memory tokens){
        uint256 n=rewardPool.rewardTokenLength();if(n>12)revert InvalidReward();tokens=new address[](n+1);tokens[0]=fxn;
        for(uint256 i;i<n;++i){address t=rewardPool.rewardTokens(i);if(t==address(0)||t==want||t==address(curvePool)||t==fxn)continue;
            bool duplicate;for(uint256 j;j<=i;++j)if(tokens[j]==t)duplicate=true;if(!duplicate)tokens[i+1]=t;}
    }
    function _bindRewardSets(address[] memory boost,address[] memory convex) private {
        for(uint8 lane=1;lane<=2;++lane){address[] memory tokens=lane==1?boost:convex;
            for(uint256 i;i<tokens.length;++i){address t=tokens[i];if(t==address(0)||t==want||t==address(staking)||t==address(curvePool))continue;
                uint8 previous=rewardLane[t];if(previous!=0 && previous!=lane)revert InvalidReward();if(previous==0)rewardLane[t]=lane;}}
    }
    function rewardTokens() external view returns(address[] memory boost,address[] memory convex){return(_boostRewards(),_convexRewards());}
    function harvest() external nonReentrant{_harvest(msg.sender);}
    function harvest(address recipient) external nonReentrant{_harvest(recipient);}
    function _harvest(address recipient) private {
        if(recipient==address(0))revert InvalidRecipient();address[] memory boost=_boostRewards();address[] memory convex=_convexRewards();
        _bindRewardSets(boost,convex);_harvestPosition(0,recipient,boost);_harvestPosition(1,recipient,convex);emit MasterHarvest(recipient);
        if(gasleft()>450_000){try IVaultAPYUnifiedV43(vault).updateAPY{gas:300_000}(){}catch{}}
    }
    function _fee(uint256 gross,uint16 bps) private pure returns(uint256 f,uint256 caller){f=gross*bps/MAX_BPS;caller=f*CALL_SHARE_BPS/MAX_BPS;}
    function _harvestPosition(uint8 position,address recipient,address[] memory tokens) private {
        uint256 beforeWant=_want();
        if(position==0){address[] memory claimed=staking.harvest_and_claim();_bindRewardSets(claimed,new address[](0));tokens=claimed;}else convexVault.getReward();
        uint16 bps=position==0?BOOST_FEE_BPS:CONVEX_FEE_BPS;
        (uint256 fees,uint256 callerFees)=_fee(_want()-beforeWant,bps);uint256 currentWant=_want();
        for(uint256 i;i<tokens.length;++i){address t=tokens[i];if(t==address(0)||t==want||t==address(staking)||t==address(curvePool))continue;
            uint256 amount=IERC20(t).balanceOf(address(this));if(amount==0)continue;IERC20(t).forceApprove(swapper,amount);
            try IBeefySwapperV2(swapper).swap(t,want,amount) returns(uint256){
                uint256 next=_want();uint256 gain=next-currentWant;currentWant=next;if(gain==0)revert SwapOutputZero();
                (uint256 f,uint256 cf)=_fee(gain,bps);fees+=f;callerFees+=cf;
